namespace Fm1Track {
struct Texture {QJsonObject resource;int width=0,height=0,levels=0,code=0;bool supported=false;};
struct Part {QString name;QJsonObject resource;int id=0,kind=0,mode=0,stride=0;quint32 flags=0;qint64 descriptor=0,vertices=0,indexOffset=0,indexCount=0,triangles=0;QVector<int> textures;};
struct Catalog {QMap<int,Texture> textures;QVector<Part> parts;float uvScale[2]{};int special=0;QString error;};
inline ReadRequest memory(const QByteArray &b){auto m=std::make_shared<MemoryData>();m->size=b.size();for(qint64 p=0;p<b.size();p+=MemoryData::BlockSize)m->blocks.append(b.mid(p,MemoryData::BlockSize));ReadRequest r;r.memory=m;r.expectedSize=b.size();return r;}
inline Catalog parse(const QByteArray &b,const std::atomic_bool &cancel){
    Catalog out;auto fail=[&](QString s){out.parts.clear();out.error=s;return out;};auto fits=[&](qint64 p,qint64 n){return NativeResources::range(p,n,b.size());};auto u=[&](qint64 p){return qFromLittleEndian<quint32>(b.constData()+p);};auto half=[&](qint64 p){return qFromLittleEndian<quint16>(b.constData()+p);};
    if(b.size()<306||u(0)!=0xc0c0aaaa||u(4)!=15)return out;qint64 count=u(8),strings=306+count*24;if(count<1||count>1000000||!fits(306,count*24)||!fits(strings,u(24)))return out;
    qint64 meta=strings+u(24),metaSize=u(40);if(!fits(meta,metaSize))return fail("FM1 metadata range exceeds the CAB.");
    QMap<QString,QJsonObject> entries;QMap<QString,qint64> extras;
    for(int i=0;i<count;++i){if(cancel.load())return fail("FM1 scan canceled.");qint64 p=306+i*24,at=u(p),size=u(p+4),decoded=u(p+8),nameAt=u(p+12),extra=u(p+16);if(nameAt>=u(24)||!fits(at,size)||size!=decoded||at<meta+metaSize)return fail("Unsupported FM1 track CAB member.");auto zero=b.indexOf('\0',strings+nameAt);if(zero<0||zero>=meta)return fail("Invalid FM1 resource name.");auto name=QString::fromUtf8(b.mid(strings+nameAt,zero-strings-nameAt));if(entries.contains(name))return fail("Duplicate FM1 resource name.");entries[name]=NativeResources::entry(name,at,size,size,"stored","Forza Motorsport CAB");extras[name]=extra;}
    QString modelName;for(auto it=entries.cbegin();it!=entries.cend();++it)if(it.key().startsWith("model_")&&!it.key().endsWith("_splines")){if(!modelName.isEmpty())return fail("Multiple FM1 model tables require an explicit assembly profile.");modelName=it.key();}if(modelName.isEmpty()||!entries.contains("resfullnametable"))return out;
    auto resource=[&](const QString &name){auto r=entries.value(name);return b.mid(r["offset"].toString().toLongLong(),r["decodedBytes"].toString().toLongLong());};
    auto table=resource("resfullnametable");if(table.size()<4)return fail("Missing FM1 resource ID table.");qint64 ids=qFromLittleEndian<quint32>(table.constData());if(ids<1||ids>count||4+ids*4>table.size())return fail("Invalid FM1 resource ID count.");QMap<int,QString> names;
    for(int i=0;i<ids;++i){qint64 p=qFromLittleEndian<quint32>(table.constData()+4+i*4);if(!NativeResources::range(p,5,table.size())||qFromLittleEndian<quint32>(table.constData()+p)!=quint32(i))return fail("Invalid FM1 resource ID binding.");auto zero=table.indexOf('\0',p+4);if(zero<0)return fail("Invalid FM1 resource ID name.");auto name=QString::fromUtf8(table.mid(p+4,zero-p-4));if(!entries.contains(name)&&entries.contains(name.toLower()))name=name.toLower();if(!entries.contains(name))return fail("FM1 resource ID cannot be resolved.");names[i]=name;}
    for(auto it=names.cbegin();it!=names.cend();++it){if(!it.value().startsWith("tex_"))continue;auto name=it.value();auto extra=extras[name];if(extra<0||extra+20>metaSize)return fail("Invalid FM1 texture metadata.");auto fmt=u(meta+extra+12);Texture t;t.resource=entries[name];t.width=1<<((fmt>>20)&15);t.height=1<<((fmt>>24)&15);t.levels=(fmt>>16)&15;t.code=(fmt>>8)&255;qint64 expected=0;if(t.levels>0&&t.levels<=14&&imageValidSize(t.width,t.height)&&(t.code==12||t.code==15))for(int k=0;k<t.levels;++k)expected+=qint64(qMax(1,(qMax(1,t.width>>k)+3)/4))*qMax(1,(qMax(1,t.height>>k)+3)/4)*(t.code==12?8:16);t.supported=expected>0&&expected==t.resource["decodedBytes"].toString().toLongLong();out.textures[it.key()]=t;}
    auto scales=resource("texcoordscale");if(scales.size()!=8)return fail("Missing FM1 UV scale.");for(int k=0;k<2;++k){auto bits=qFromLittleEndian<quint32>(scales.constData()+k*4);std::memcpy(out.uvScale+k,&bits,4);if(!std::isfinite(out.uvScale[k])||out.uvScale[k]<=0||out.uvScale[k]>1e6)return fail("Invalid FM1 UV scale.");}
    auto models=resource(modelName),labels=resource("meshnametable_track");if(models.size()<4||labels.size()<4)return fail("Missing FM1 model/name tables.");auto mu=[&](qint64 p){return qFromLittleEndian<quint32>(models.constData()+p);};qint64 meshes=mu(0);if(meshes<1||meshes>1000000||4+meshes*4>models.size()||qFromLittleEndian<quint32>(labels.constData())!=meshes||4+meshes*4>labels.size())return fail("Invalid FM1 mesh tables.");
    // Descriptor +4 is a runtime pointer in retail tracks, not a required USER magic.
    for(int i=0;i<meshes;++i){if(cancel.load())return fail("FM1 scan canceled.");qint64 p=mu(4+i*4),end=i+1<meshes?mu(8+i*4):models.size();if(p<4+meshes*4||end<p+24||end>models.size())return fail("Invalid FM1 mesh descriptor.");Part part;part.id=i;part.descriptor=entries[modelName]["offset"].toString().toLongLong()+p;part.flags=mu(p);part.indexCount=mu(p+8);part.indexOffset=mu(p+12);int buffer=qFromLittleEndian<quint16>(models.constData()+p+16);part.mode=qFromLittleEndian<quint16>(models.constData()+p+18);part.kind=quint8(models[p+20]);if(!names.contains(buffer)||!names[buffer].startsWith("vbuff_"))return fail("Invalid FM1 vertex buffer binding.");part.resource=entries[names[buffer]];
        QVector<int> offsets;switch(part.kind){case 15:case 16:case 1:offsets={22};part.stride=20;break;case 11:case 14:case 6:offsets={22,24};part.stride=24;break;case 9:offsets={22,24,26,28};part.stride=32;break;case 10:offsets={22,24,26};part.stride=28;break;case 13:offsets={22,24,26};part.stride=24;break;case 18:offsets={22,24};part.stride=20;break;case 23:offsets={22};part.stride=32;break;case 17:offsets={40,42};part.stride=44;break;case 21:offsets={28};part.stride=40;break;default:++out.special;continue;}
        for(int at:offsets){if(p+at+2>end)return fail("Invalid FM1 texture reference field.");int id=qFromLittleEndian<quint16>(models.constData()+p+at);if(!out.textures.contains(id))return fail("FM1 mesh texture reference is unresolved.");part.textures.append(id);}
        if(part.indexCount<3||part.indexOffset<part.stride*3||part.indexOffset%part.stride||part.indexOffset+part.indexCount*2!=part.resource["decodedBytes"].toString().toLongLong())return fail("Invalid FM1 geometry ranges.");part.vertices=part.indexOffset/part.stride;if(!AssetMemory::fits(part.vertices,part.indexCount))return fail("FM1 mesh exceeds the configured memory budget.");
        qint64 nameAt=qFromLittleEndian<quint32>(labels.constData()+4+i*4);if(nameAt<4+meshes*4||nameAt>=labels.size())return fail("Invalid FM1 mesh name.");auto zero=labels.indexOf('\0',nameAt);if(zero<0)return fail("Unterminated FM1 mesh name.");part.name=QString::fromUtf8(labels.mid(nameAt,zero-nameAt));
        auto bytes=resource(names[buffer]);qint64 run=0;quint16 a=0,c=0;for(qint64 k=0;k<part.indexCount;++k){auto v=qFromLittleEndian<quint16>(bytes.constData()+part.indexOffset+k*2);if(v>=part.vertices)return fail("FM1 face index exceeds its vertex buffer.");if(part.mode==6&&run>=2&&a!=c&&a!=v&&c!=v)++part.triangles;a=c;c=v;++run;}
        if(part.kind==17||part.kind==21){++out.special;continue;}if(part.mode!=6||!part.triangles)return fail("Unsupported FM1 direct geometry topology.");out.parts.append(part);
    }
    return out;
}
struct Session {QMutex mutex;QByteArray bytes,key;ReadRequest decoded;Catalog catalog;QMap<int,QImage> images;};
inline QByteArray identity(const ReadRequest &r,const PatchList &patches,const QJsonObject &archive){QByteArray key=r.path.toUtf8()+QByteArray::number(r.expectedSize)+r.expectedModified.toString(Qt::ISODateWithMs).toUtf8()+QByteArray::number(quintptr(r.memory.get()))+QJsonDocument(archive).toJson(QJsonDocument::Compact);for(const auto &p:patches){key+=QByteArray::number(p.offset);key+=p.bytes;}return QCryptographicHash::hash(key,QCryptographicHash::Sha256);}
inline bool load(Session &s,ReadRequest source,const PatchList &patches,const QJsonObject &archive,const std::atomic_bool &cancel,QString &error){
    auto check=source;check.offset=0;check.length=0;error=readPage(check).error;if(!error.isEmpty()||cancel.load()){if(error.isEmpty())error="FM1 decoding canceled.";return false;}auto key=identity(source,patches,archive);if(s.key==key&&!s.bytes.isEmpty())return true;
    QByteArray bytes;if(archive.isEmpty())bytes=NativeResources::read(source,patches,0,source.expectedSize,cancel,error,AssetMemory::bytes()/4);else{auto data=NativeResources::extract(source,patches,archive,cancel);bytes=data.bytes;error=data.error;}if(!error.isEmpty())return false;if(bytes.size()>AssetMemory::bytes()/4){error="FM1 track exceeds the configured scan budget.";return false;}auto catalog=parse(bytes,cancel);if(!catalog.error.isEmpty()||catalog.parts.isEmpty()){error=catalog.error.isEmpty()?"No supported FM1 track geometry.":catalog.error;return false;}s.bytes=bytes;s.catalog=catalog;s.key=key;s.decoded={};s.images.clear();return true;
}
inline QImage texture(Session &s,int id,const std::atomic_bool &cancel,QString &error){if(s.images.contains(id))return s.images[id];if(!s.catalog.textures.contains(id)){error="Unknown FM1 texture ID.";return {};}const auto &t=s.catalog.textures[id];if(!t.supported){error="FM1 texture uses unresolved atlas/packing metadata.";return {};}ImageRecipe recipe;recipe.width=t.width;recipe.height=t.height;recipe.format=t.code==12?"BC1":"BC3";auto offset=t.resource["offset"].toString().toLongLong(),size=t.resource["decodedBytes"].toString().toLongLong();auto image=decodeTextureData(s.bytes.mid(offset,size),{},recipe,error,cancel).convertToFormat(QImage::Format_RGBA8888);if(!image.isNull()&&!cancel.load())s.images[id]=image;return image;}
inline QJsonObject scan(ReadRequest source,const PatchList &patches,const QJsonObject &resources,const std::atomic_bool &cancel){
    QJsonObject archive;if(resources["format"]=="Zlib"){for(auto v:resources["entries"].toArray()){auto r=v.toObject();if(r["codec"]=="zlib-blocks"&&r["supported"].toBool()){archive=r;break;}}if(archive.isEmpty())return {};}else if(resources["format"]!="Forza Motorsport CAB")return {};
    Session session;QString error;if(!load(session,source,patches,archive,cancel,error))return {{"notes",QJsonArray{QString("FM1 track: %1").arg(error)}}};QJsonArray candidates,images,notes;auto &catalog=session.catalog;
    for(const auto &p:catalog.parts){QJsonArray bindings;for(int id:p.textures)bindings.append(QJsonObject{{"id",id},{"name",catalog.textures[id].resource["name"]},{"decoded",catalog.textures[id].supported}});candidates.append(QJsonObject{{"name","FM1 track / "+p.name+(p.name.contains("sky",Qt::CaseInsensitive)?" / optional sky":"")},{"profileId","native-fm1-track"},{"profileName","FM1 track geometry + textures"},{"nativeDecoder",true},{"fm1ArchiveResource",archive},{"fm1TrackPart",p.id},{"fm1FlipU",ImportPreferences::fm1FlipU.load()},{"fm1FlipV",ImportPreferences::fm1FlipV.load()},{"objectOffset",QString::number(p.descriptor)},{"triangleCount",p.triangles},{"materialGroups",bindings},{"settings",QJsonObject{{"vertexOffset",QString::number(p.resource["offset"].toString().toLongLong())},{"vertexCount",p.vertices},{"indexCount",p.triangles*3}}},{"basis","Validated model/resource IDs, independent strips, Float32 positions and packed UV0. Supported primary texture assigned automatically; unresolved texture formats leave geometry untextured; secondary/detail/lightmap references retained in material metadata. Additional shader layers and special vegetation/crowd geometry are not applied. Sky is optional."}});}
    QList<QJsonValue> ordered;for(auto c:candidates)ordered.append(c);std::stable_sort(ordered.begin(),ordered.end(),[](const QJsonValue &a,const QJsonValue &b){bool skyA=a.toObject()["name"].toString().contains("optional sky"),skyB=b.toObject()["name"].toString().contains("optional sky");if(skyA!=skyB)return !skyA;return a.toObject()["settings"].toObject()["vertexCount"].toInteger()>b.toObject()["settings"].toObject()["vertexCount"].toInteger();});
    candidates={};for(auto c:ordered)candidates.append(c);
    int unsupported=0;for(auto it=catalog.textures.cbegin();it!=catalog.textures.cend();++it){const auto &t=it.value();if(!t.supported){++unsupported;continue;}images.append(QJsonObject{{"name",t.resource["name"]},{"profileId","native-fm1-track-texture"},{"nativeDecoder",true},{"fm1ArchiveResource",archive},{"fm1TextureId",it.key()},{"width",t.width},{"height",t.height},{"basis","Xbox texture metadata and exact BC mip-chain size. Extracted from the same FM1 track snapshot."},{"settings",QJsonObject{{"offset",t.resource["offset"]},{"width",t.width},{"height",t.height},{"format",t.code==12?"BC1":"BC3"}}}});}
    notes.append(QString("FM1 track: %1 direct meshes and %2 textures. Primary textures are linked on preview and retained on FBX/GLB export. Use Ctrl/Shift or Select All; optional sky can be deselected.").arg(candidates.size()).arg(images.size()));notes.append(QString("Not imported: %1 meshes using unsupported/special shaders, %2 textures using unresolved packing or formats. Additional lightmap/detail/blend shader layers remain source references, not approximated shaders.").arg(catalog.special).arg(unsupported));return {{"candidates",candidates},{"images",images},{"notes",notes}};
}
inline MeshResult decode(ReadRequest source,const PatchList &patches,const QJsonObject &candidate,const std::atomic_bool &cancel,Session *shared=nullptr){
    Session local;auto &s=shared?*shared:local;QMutexLocker lock(&s.mutex);MeshResult out;auto fail=[&](QString e){out.mesh.reset();out.error=e;return out;};QString error;if(!load(s,source,patches,candidate["fm1ArchiveResource"].toObject(),cancel,error))return fail(error);int id=candidate["fm1TrackPart"].toInt(-1);auto found=std::find_if(s.catalog.parts.cbegin(),s.catalog.parts.cend(),[&](const Part &p){return p.id==id&&QString::number(p.descriptor)==candidate["objectOffset"].toString();});if(found==s.catalog.parts.cend())return fail("FM1 mesh no longer matches its scan.");const auto &p=*found;qint64 base=p.resource["offset"].toString().toLongLong();MeshSpec spec;spec.vertexOffset=base;spec.vertexCount=p.vertices;spec.vertexStride=p.stride;spec.positionType="Float32";spec.positionScale=1;spec.uv=false;spec.normals=false;spec.indexOffset=base+p.indexOffset;spec.indexCount=p.indexCount;spec.indexStride=2;spec.indexType="UInt16";if(!s.decoded.memory)s.decoded=memory(s.bytes);out=readMesh(s.decoded,{},spec);if(!out.mesh)return out;// Xbox clockwise strips need reversal for outward normals in the portable mesh.
    for(qsizetype i=0;i<out.mesh->triangles.size();i+=3){std::swap(out.mesh->triangles[i+1],out.mesh->triangles[i+2]);auto &f=out.mesh->faceSources[i/3];std::swap(f.offsets[1],f.offsets[2]);std::swap(f.indexSlots[1],f.indexSlots[2]);}for(auto &v:out.mesh->vertices)for(auto &n:v.normal)n=-n;
    out.mesh->hasUvs=true;out.surface=std::make_shared<MeshSurface>();
    const bool flipU=candidate["fm1FlipU"].toBool(false);const bool flipV=candidate["fm1FlipV"].toBool(false);
    for(qsizetype i=0;i<out.mesh->vertices.size();++i){if((i&4095)==0&&cancel.load())return fail("FM1 preview canceled.");auto &v=out.mesh->vertices[i];for(int a=0;a<2;++a){auto bits=qFromLittleEndian<quint16>(s.bytes.constData()+base+i*p.stride+16+a*2);v.uv[a]=float((int(bits)-32768)*double(s.catalog.uvScale[a])/65535.);}if(flipU)v.uv[0]=1.f-v.uv[0];if(flipV)v.uv[1]=1.f-v.uv[1];if(v.normal[0]==0&&v.normal[1]==0&&v.normal[2]==0)v.normal[1]=1;}
    QJsonArray bindings;for(int tid:p.textures){auto t=s.catalog.textures[tid];auto name=t.resource["name"].toString();bindings.append(QJsonObject{{"resourceId",tid},{"name",name},{"role",tid==p.textures.first()?"base color":"additional source shader layer"},{"applied",tid==p.textures.first()&&t.supported}});if(t.supported){auto image=texture(s,tid,cancel,error);if(image.isNull())return fail(error.isEmpty()?"FM1 texture decoding canceled.":error);out.surface->textureLibrary[name]=image;}}
    int primary=p.textures.first();if(s.catalog.textures[primary].supported){out.surface->texture=texture(s,primary,cancel,error);if(out.surface->texture.isNull())return fail(error);}out.surface->textureName=s.catalog.textures[primary].resource["name"].toString();out.surface->material.name=QString("FM1 / %1 / shader %2").arg(p.name).arg(p.kind);out.surface->material.alphaMask=out.surface->texture.hasAlphaChannel();out.surface->material.doubleSided=true;out.surface->material.sourceBindings={{"format","FM1 XB2"},{"shaderKind",p.kind},{"textures",bindings},{"additionalLayersApplied",false}};
    if(!candidate["fm1ArchiveResource"].toObject().isEmpty()){out.mesh->vertexOffsets.clear();out.mesh->faceSources.clear();}auto check=source;check.offset=0;check.length=0;auto final=readPage(check);if(!final.error.isEmpty()||cancel.load())return fail(final.error.isEmpty()?"FM1 decoding canceled.":final.error);return out;
}
inline DecodedImage decodeImage(ReadRequest source,const PatchList &patches,const QJsonObject &candidate,const std::atomic_bool &cancel,Session *shared=nullptr){Session local;auto &s=shared?*shared:local;QMutexLocker lock(&s.mutex);DecodedImage out;if(!load(s,source,patches,candidate["fm1ArchiveResource"].toObject(),cancel,out.error))return out;out.image=texture(s,candidate["fm1TextureId"].toInt(-1),cancel,out.error);auto check=source;check.offset=0;check.length=0;auto result=readPage(check);if(!result.error.isEmpty()||cancel.load()){out.image={};out.error=result.error.isEmpty()?"FM1 image decoding canceled.":result.error;}return out;}
}
